using System;
using System.Collections.Generic;
using System.IO;
using XGrid.Memory;
using Xunit;

namespace XGrid.Cpu.Tests;

/// <summary>
/// Differential tests against an independent x86 implementation.
///
/// The corpus is generated by <c>tools/cpu-oracle/oracle.py</c>: the same code
/// bytes, registers and flags are executed on QEMU's TCG core (via Unicorn) and
/// on this CPU, and the final architectural state must match.  Both sides run a
/// common epilogue (<c>fxsave [0x1f0000]</c> + <c>int $0x30</c>), so x87, MMX
/// and SSE state is compared through the architectural FXSAVE image.
/// </summary>
public sealed class CpuOracleTests
{
    private const uint CodeBase = 0x00040000;
    private const uint CaseStride = 128;
    private const uint PageBase = 0x00200000;
    private const uint PageStride = 0x2000;
    private const uint FxsaveAddress = 0x001F0000;
    private const uint MemorySize = 0x00600000;
    private const int FxsaveSize = 512;
    private const int PageDumpSize = 256;

    private static readonly byte[] FxsaveSentinel = CreateSentinel();

    [Fact]
    public void InstructionCorpus_MatchesIndependentOracle()
    {
        string root = FindCorpusDirectory();
        CpuOracleDocument document = CpuOracleLoader.Load(File.ReadAllText(Path.Combine(root, "int.json")));
        byte[] records = File.ReadAllBytes(Path.Combine(root, "int.dat"));

        Assert.Equal(FxsaveSize + PageDumpSize, document.RecordSize);
        Assert.Equal(document.Cases.Count * document.RecordSize, records.Length);

        var memory = new PhysicalMemory(MemorySize);
        var bus = new AddressSpace(memory, UnmappedAccessPolicy.Throw);
        memory.Write32(0x001F1000, 0x00001F80); // MXCSR reset value used by the common prologue
        var failures = new List<string>();

        foreach (CpuOracleCase testCase in document.Cases)
        {
            string? failure = RunCase(memory, bus, testCase, records, document.RecordSize);
            if (failure is not null)
            {
                failures.Add($"{testCase.Name}: {failure}");
            }
        }

        Assert.True(failures.Count == 0, string.Join(Environment.NewLine, failures));
    }

    private static string? RunCase(
        PhysicalMemory memory,
        AddressSpace bus,
        CpuOracleCase testCase,
        byte[] records,
        int recordSize)
    {
        byte[] code = CpuTestRunner.ParseBytes(testCase.Code);
        uint codeAddress = CodeBase + ((uint)testCase.Record * CaseStride);
        memory.WriteSpan(codeAddress, code);
        memory.WriteSpan(FxsaveAddress, FxsaveSentinel);

        var cpu = new XboxCpu(bus);
        cpu.Reset();
        cpu.Context.Cr0 = 1;
        cpu.Context.CodeSegment32 = true;
        cpu.Context.SetSegment(SegmentRegister.Cs, 0x08, 0);
        cpu.Context.SetSegment(SegmentRegister.Ds, 0x10, 0);
        cpu.Context.SetSegment(SegmentRegister.Ss, 0x10, 0);
        cpu.Context.SetSegment(SegmentRegister.Es, 0x10, 0);
        cpu.Context.SetSegment(SegmentRegister.Fs, 0x10, 0);
        cpu.Context.SetSegment(SegmentRegister.Gs, 0x10, 0);
        cpu.Context.Eflags = CpuTestRunner.ParseUInt32(testCase.Eflags) | FlagBits.Reserved1;

        foreach (KeyValuePair<string, string> register in testCase.Registers)
        {
            SetRegister(cpu.Context, register.Key, CpuTestRunner.ParseUInt32(register.Value));
        }

        cpu.Context.Eip = codeAddress;

        try
        {
            cpu.Execute(256);
            return $"did not reach the stop marker (EIP=0x{cpu.Context.Eip:X8})";
        }
        catch (UnhandledGuestException exception) when (exception.Vector == 0x30)
        {
            // Expected stop marker.
        }
        catch (UnsupportedInstructionException exception)
        {
            return $"unsupported instruction: {exception.Message}";
        }
        catch (UnhandledGuestException exception)
        {
            return $"unexpected guest exception {exception.Vector} at EIP=0x{exception.Eip:X8}";
        }

        uint expectedEip = CpuTestRunner.ParseUInt32(testCase.Expect.Eip);
        if (cpu.Context.Eip != expectedEip)
        {
            return $"EIP expected 0x{expectedEip:X8}, got 0x{cpu.Context.Eip:X8}";
        }

        foreach (KeyValuePair<string, string> register in testCase.Expect.Registers)
        {
            uint expected = CpuTestRunner.ParseUInt32(register.Value);
            uint actual = GetRegister(cpu.Context, register.Key);
            if (actual != expected)
            {
                return $"{register.Key.ToUpperInvariant()} expected 0x{expected:X8}, got 0x{actual:X8}";
            }
        }

        uint expectedFlags = CpuTestRunner.ParseUInt32(testCase.Expect.Eflags);
        uint flagsMask = CpuTestRunner.ParseUInt32(testCase.FlagsMask);
        if ((cpu.Context.Eflags & flagsMask) != (expectedFlags & flagsMask))
        {
            return $"EFLAGS expected 0x{expectedFlags & flagsMask:X8}, got 0x{cpu.Context.Eflags & flagsMask:X8} (mask 0x{flagsMask:X8})";
        }

        ReadOnlySpan<byte> expectedRecord = new(records, testCase.Record * recordSize, recordSize);
        Span<byte> actualRecord = stackalloc byte[FxsaveSize + PageDumpSize];
        memory.GetSpan(FxsaveAddress, FxsaveSize).CopyTo(actualRecord[..FxsaveSize]);
        memory.GetSpan(PageBase + ((uint)testCase.Record * PageStride), PageDumpSize)
            .CopyTo(actualRecord[FxsaveSize..]);

        for (int i = 0; i < FxsaveSize; i++)
        {
            if (!IsComparedFxsaveByte(i))
            {
                continue;
            }

            if (actualRecord[i] != expectedRecord[i])
            {
                return $"FXSAVE +0x{i:X2} expected 0x{expectedRecord[i]:X2}, got 0x{actualRecord[i]:X2}";
            }
        }

        for (int i = 0; i < PageDumpSize; i++)
        {
            int offset = FxsaveSize + i;
            if (actualRecord[offset] != expectedRecord[offset])
            {
                int start = Math.Max(0, i - 8);
                int end = Math.Min(PageDumpSize, i + 8);
                return $"memory +0x{i:X2} expected 0x{expectedRecord[offset]:X2}, got 0x{actualRecord[offset]:X2}"
                       + $" (expected {Convert.ToHexString(expectedRecord[(FxsaveSize + start)..(FxsaveSize + end)])}"
                       + $" actual {Convert.ToHexString(actualRecord[(FxsaveSize + start)..(FxsaveSize + end)])})";
            }
        }

        return null;
    }

    private static string FindCorpusDirectory()
    {
        DirectoryInfo? directory = new(AppContext.BaseDirectory);
        while (directory is not null && directory.Parent is not null)
        {
            string candidate = Path.Combine(directory.FullName, "tests", "XGrid.Cpu.Tests", "cpu-oracle");
            if (File.Exists(Path.Combine(candidate, "int.json")))
            {
                return candidate;
            }

            directory = directory.Parent;
        }

        throw new DirectoryNotFoundException("tests/XGrid.Cpu.Tests/cpu-oracle/int.json not found above the test output directory.");
    }

    private static bool IsComparedFxsaveByte(int offset)
    {
        // FCW/FSW and MXCSR are architectural.  The abridged tag, FOP, FPU
        // pointers, MXCSR mask and the contents of empty register slots are
        // implementation-visible only; values are compared through the memory
        // the case stores them to.
        return offset < 4 || (offset is >= 24 and < 28);
    }

    private static byte[] CreateSentinel()
    {
        byte[] sentinel = new byte[FxsaveSize];
        Array.Fill(sentinel, (byte)0xFF);
        return sentinel;
    }

    private static void SetRegister(XboxContext context, string name, uint value)
    {
        switch (name.ToUpperInvariant())
        {
            case "EAX": context.WriteRegister(Gpr.Eax, value); break;
            case "ECX": context.WriteRegister(Gpr.Ecx, value); break;
            case "EDX": context.WriteRegister(Gpr.Edx, value); break;
            case "EBX": context.WriteRegister(Gpr.Ebx, value); break;
            case "ESP": context.WriteRegister(Gpr.Esp, value); break;
            case "EBP": context.WriteRegister(Gpr.Ebp, value); break;
            case "ESI": context.WriteRegister(Gpr.Esi, value); break;
            case "EDI": context.WriteRegister(Gpr.Edi, value); break;
            default: throw new FormatException($"Unknown register '{name}'.");
        }
    }

    private static uint GetRegister(XboxContext context, string name)
    {
        return name.ToUpperInvariant() switch
        {
            "EAX" => context.ReadRegister(Gpr.Eax),
            "ECX" => context.ReadRegister(Gpr.Ecx),
            "EDX" => context.ReadRegister(Gpr.Edx),
            "EBX" => context.ReadRegister(Gpr.Ebx),
            "ESP" => context.ReadRegister(Gpr.Esp),
            "EBP" => context.ReadRegister(Gpr.Ebp),
            "ESI" => context.ReadRegister(Gpr.Esi),
            "EDI" => context.ReadRegister(Gpr.Edi),
            _ => throw new FormatException($"Unknown register '{name}'."),
        };
    }
}

